import {DEMO_CODES,maskPhone,validateProfile,redeem,restore} from './model.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kk={skip:'Мазмұнға өту',demo:'ДЕМО-ТҰЖЫРЫМДАМА • СЫНАҚ КОДТАРЫ • НАҚТЫ ҰТЫС ЖОҚ',navHow:'Қалай қатысуға болады',navGifts:'Сыйлықтар',navProduct:'Біздің құрт',navFaq:'Сұрақтар',account:'Жеке кабинет',eyebrow:'КӨКШЕТАУДАН ЫСТАЛҒАН ҚҰРТ',hero1:'ТАНЫС',hero2:'ДӘМ.',hero3:'ЖАҢА',hero4:'СЫЙЛЫҚТАР.',heroDesc:'Сүйікті құртыңды аш, кодтарды тірке және қуанышты сәттерді жина.',registerCode:'Кодты тіркеу',howLink:'Бұл қалай жұмыс істейді',heroNote:'Демоны байқап көр — өнім сатып алу қажет емес.',round1:'ДӘСТҮРЛЕР',round2:'ЖАҢА ҚАЛЫПТА',grams:'г',packLabel:'Жолға. Шайға. Өзіңмен бірге.',made:'ГОРМОЛЗАВОД • КӨКШЕТАУ',scroll:'СЫЙЛЫҚТАРҒА ҚАРАЙ ТӨМЕН ↓',howEyebrow:'БӘРІ ҚАПТАМАДАН БАСТАЛАДЫ',howTitle:'Үш қадам.<br>Бір дәмді әдет.',step1:'Құртты аш',step1desc:'Пеналдың ішінен бірегей кодты тап. Демода төмендегі сынақ кодын қолдан.',step2:'Кодты тірке',step2desc:'Демо-профиль жасап, кодты енгіз. Әр жаңа қаптама — тағы бір қадам.',step3:'Сыйлықтар жина',step3desc:'Кабинеттен ілгерілеуіңді бақыла және демо-сыйлықтардың жаңа деңгейлерін аш.',tryTitle:'Қазір байқап көреміз бе?',tryDesc:'Алғашқы танысуға арналған сынақ коды',tryBtn:'Байқап көру →',giftEye:'КІШКЕНТАЙ ҚУАНЫШ — ҮЛКЕН СЕБЕП',giftTitle:'Кодтарды жина.<br>Сыйлықтарды аш.',giftDisclaimer:'Бұл — үлгі: сыйлықтар мен шектер демо үшін көрсетілген. Нақты акция әлі жарияланған жоқ.',oneCode:'1 код',threeCodes:'3 код',fiveCodes:'5 код',prize1:'Көкшетаудың бір бөлшегі',prize1desc:'Заттарыңа арналған стикер дизайны',prize2:'Шай ішетін уақыт',prize2desc:'q.club кесесі тұжырымдамасы',prize3:'Дәстүрді сыйла',prize3desc:'Керамикалық құты тұжырымдамасы',demoGift:'ДЕМО-СЫЙЛЫҚ',startCollect:'Жинауды бастау',conceptLabel:'ҚАПТАМА ТҰЖЫРЫМДАМАСЫ / 120 г',productEye:'БАЛАЛЫҚТАН ТАНЫС. БҮГІНГЕ ЫҢҒАЙЛЫ.',productTitle:'Біздің құрт.<br>Сенің ырғағың.',productDesc:'«Гормолзавод» ысталған құрты — жаңа жылжымалы пеналдағы дәстүрлі дәм. Үйде шайға, оқуға немесе жолға.',ingredients:'Құрамы',ingredientsValue:'Майсыз сүзбе, ас тұзы.',format:'Жаңа формат',formatValue:'120 г • қағаз орамасы бар картон пенал.',materialNote:'Құрылым әзірленуде: орама материалы мен өнімнің сақталуын әлі растау қажет.',faqEye:'ҚАЖЕТ БОЛСА',faqTitle:'Сұрағың бар ма?',rulesLink:'Демо шарттары ↗',q1:'Кодты қайдан табамын?',a1:'Қаптама тұжырымдамасында код пеналдың ішінде орналасқан. Сайтты тексеру үшін QURT-DEMO-001 — QURT-DEMO-005 кодтары қолжетімді.',q2:'Нақты сыйлық алуға бола ма?',a2:'Қазір бұл — хакатонға арналған демонстрация. Сыйлықтар берілмейді, сатып алу қажет емес. Нақты акцияның мерзімі мен ережелері бекітілмеген.',q3:'Код неге қабылданбайды?',a3:'Кодтың жазылуын тексер. Демода бес сынақ коды ғана жұмыс істейді. Әр кодты осы браузерде бір рет қосуға болады.',q4:'Деректерім қайда сақталады?',a4:'Тек осы браузерде. Серверге ештеңе жіберілмейді. Телефон нөмірі жасырылған түрде сақталады. Ойдан шығарылған деректерді қолдан. Профильді кабинеттен жоюға болады.',lastTitle:'Қайта оралуға<br>дәмді себеп.',tryDemo:'Демоны байқап көру',footer:'AI Design Hackathon 2026 үшін жасалған тұжырымдама.<br>Бұл қолданыстағы акция емес.',privacyLink:'Деректер және құпиялық'};
Object.assign(kk,{"step1desc": "Пеналды ашып, қаптаманың ішкі жағынан бірегей кодты тап.", "step2desc": "Профиль жасап, кодты енгіз. Әр жаңа қаптама — тағы бір қадам.", "step3desc": "Кабинеттен ілгерілеуіңді бақыла: стикерлер, кесе және керамикалық құты жина.", "prize1": "q.club стикерпагы", "prize1desc": "Мінезі бар құрт — сүйікті заттарыңа арналған", "prize2": "q.club кесесі", "prize2desc": "Шайға, әңгімеге және жылы сәттерге", "prize3desc": "Сүйікті құртыңа арналған керамикалық құты", "tryDemo": "Кодты тіркеу", "footer": "Гормолзавод • Көкшетау<br>Таныс дәм. Жаңа әсерлер.", "rulesLink": "Қатысу ережелері ↗", "q2": "Сыйлықтарды қалай бақылауға болады?", "a1": "Код пеналдың ішкі жағында орналасқан. Қаптаманы ашып, кодты жеке кабинетте енгіз.", "a2": "Кабинеттегі «Сыйлықтар» бөлімін аш. Онда әр сыйлыққа дейінгі ілгерілеу көрсетілген.", "a3": "Кодтың жазылуын тексер. Әр кодты бір рет тіркеуге болады.", "a4": "Профиль мен кодтар тарихы осы браузерде сақталады. Оларды кабинеттен жоюға болады."});
const ru=Object.fromEntries($$('[data-i18n]').map(el=>[el.dataset.i18n,el.innerHTML]));
let lang='ru',state=null,view='',tab='code',pendingCode='',formDraft=null,lastFocus=null,toastTimer;
try{lang=localStorage.getItem('qurt-lang')==='kk'?'kk':'ru';state=restore(localStorage.getItem('qurt-demo-v1'));}catch{}
const t=(a,b)=>lang==='kk'?b:a;
const dialog=$('#dialog'),content=$('#dialog-content');
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function save(){try{localStorage.setItem('qurt-demo-v1',JSON.stringify(state));}catch{notify(t('Браузер запретил сохранение. Данные доступны до обновления страницы.','Браузер сақтауға тыйым салды. Деректер бет жаңартылғанша қолжетімді.'));}}
function language(next){lang=next;document.documentElement.lang=lang;$$('[data-i18n]').forEach(el=>el.innerHTML=(lang==='kk'?kk:ru)[el.dataset.i18n]??ru[el.dataset.i18n]);$$('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));$('.dialog-close').ariaLabel=t('Закрыть','Жабу');try{localStorage.setItem('qurt-lang',lang);}catch{}if(dialog.open)render();}
function open(next){view=next;lastFocus=document.activeElement;render();if(!dialog.open)dialog.showModal();}
function close(){dialog.close();view='';formDraft=null;lastFocus?.focus();}
function lead(title){return `<p class="dialog-eyebrow">q.club</p><h2 id="dialog-title">${title}</h2>`;}
function register(){const f=formDraft??{};content.innerHTML=lead(t('Давай знакомиться','Танысайық'))+`<p>${t('Создай профиль, чтобы регистрировать коды и следить за подарками.','Кодтарды тіркеу және сыйлықтарды бақылау үшін профиль жаса.')}</p><form id="register-form"><div class="form-grid"><label class="field full">${t('Имя','Аты')}<input name="name" required minlength="2" maxlength="60" autocomplete="off" placeholder="${t('Например, Айдана','Мысалы, Айдана')}" value="${esc(f.name??'')}"></label><label class="field full">${t('Телефон','Телефон')}<input name="phone" type="tel" required autocomplete="off" inputmode="tel" placeholder="+7 700 000 00 00" value="${esc(f.phone??'')}"></label><label class="field">${t('Город','Қала')}<input name="city" required minlength="2" maxlength="60" autocomplete="off" placeholder="${t('Кокшетау','Көкшетау')}" value="${esc(f.city??'')}"></label><label class="field">${t('Возрастная группа','Жас тобы')}<select name="age" required><option value="">${t('Выбрать','Таңдау')}</option>${['18–24','25–34','35–44','45+'].map(a=>`<option ${f.age===a?'selected':''}>${a}</option>`).join('')}</select></label></div><label class="check"><input type="checkbox" name="consent" required ${f.consent?'checked':''}><span>${t('Согласен с хранением профиля в этом браузере.','Профильдің осы браузерде сақталуына келісемін.')} <button type="button" data-action="privacy">${t('Подробнее','Толығырақ')}</button></span></label><div class="form-error" role="alert" id="form-error"></div><button class="button blue" type="submit">${t('Создать профиль →','Профиль жасау →')}</button></form>`;
$('#register-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget),p={name:String(data.get('name')).trim(),phone:String(data.get('phone')),city:String(data.get('city')).trim(),age:data.get('age'),consent:data.has('consent')};if(!validateProfile(p)){$('#form-error').textContent=t('Проверь поля: телефон должен содержать +7 и ещё 10 цифр.','Өрістерді тексер: телефонда +7 және тағы 10 сан болуы керек.');return;}state={profile:{name:p.name,phone:maskPhone(p.phone),city:p.city,age:p.age,consentAt:new Date().toISOString()},codes:[]};save();formDraft=null;view='account';tab='code';render();});}
function cabinet(){const n=state.codes.length;content.innerHTML=lead(t('Твой Qurt Club','Сенің Qurt Club кабинетін'))+`<div class="profile-bar"><strong>${esc(state.profile.name)}</strong><span>${esc(state.profile.city)} · ${esc(state.profile.phone)}</span></div><div class="count-bubble"><strong>${n} / 5</strong><span>${t('кодов зарегистрировано','код тіркелді')}</span><div class="progress" role="progressbar" aria-label="${t('Прогресс кодов','Кодтар саны')}" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="5"><span style="width:${n*20}%"></span></div><span>${n>=5?t('Все уровни открыты!','Барлық деңгейлер ашылды!'):t('Каждый новый код — ещё один шаг.','Әр жаңа код — тағы бір қадам.')}</span></div><div class="tabs" aria-label="${t('Разделы кабинета','Кабинет бөлімдері')}">${[['code',t('Добавить код','Код қосу')],['history',t('Мои коды','Менің кодтарым')],['rewards',t('Награды','Сыйлықтар')]].map(([v,label])=>`<button data-tab="${v}" class="${tab===v?'active':''}" aria-pressed="${tab===v}">${label}</button>`).join('')}</div><div id="tab-content"></div><button class="danger-link" data-action="delete">${t('Удалить профиль и прогресс','Профиль мен ілгерілеуді жою')}</button>`;
const area=$('#tab-content');if(tab==='code'){area.innerHTML=`<form id="code-form"><label class="field">${t('Код с упаковки','Қаптамадағы код')}<input class="code-field" name="code" maxlength="30" required autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="QURT-DEMO-001" value="${esc(pendingCode)}"></label><div class="form-error" id="form-error" role="alert"></div><button class="button blue" type="submit">${t('Зарегистрировать код →','Кодты тіркеу →')}</button></form>`;pendingCode='';$('#code-form').addEventListener('submit',e=>{e.preventDefault();const result=redeem(state.codes,new FormData(e.currentTarget).get('code'));if(result.error){$('#form-error').textContent=result.error==='duplicate'?t('Этот код уже зарегистрирован. Попробуй следующий.','Бұл код тіркелген. Келесі кодты қолданып көр.'):t('Код не найден. Проверь символы и попробуй ещё раз.','Код табылмады. Таңбаларды тексеріп, қайта енгіз.');return;}state.codes=result.codes;save();render();notify(t('Код зарегистрирован! Прогресс обновлён.','Код тіркелді! Ілгерілеу жаңартылды.'));});}else if(tab==='history'){area.innerHTML=n?state.codes.map(x=>`<div class="history-item"><div><strong>${esc(x.code)}</strong><small>${esc(new Date(x.date).toLocaleString(lang==='kk'?'kk-KZ':'ru-KZ'))}</small></div><span class="success">✓</span></div>`).join(''):`<p class="empty">${t('Пока нет кодов. Добавь первый на соседней вкладке.','Кодтар әлі жоқ. Алғашқы кодты көрші бөлімде қос.')}</p>`;}else{area.innerHTML=[[1,t('Стикерпак q.club','q.club стикерпагы')],[3,t('Кружка q.club','q.club кесесі')],[5,t('Керамическая баночка','Керамикалық құты')]].map(([threshold,label])=>`<div class="reward-row"><span>${label}<br><small>${threshold} ${t('код(а)','код')}</small></span><strong>${n>=threshold?t('Открыто ✓','Ашылды ✓'):t('Ещё '+(threshold-n)+' код(а)', 'Тағы '+(threshold-n)+' код')}</strong></div>`).join('');}}
function legal(kind){if(view==='register'){const f=$('#register-form');if(f){const d=new FormData(f);formDraft={name:d.get('name'),phone:d.get('phone'),city:d.get('city'),age:d.get('age'),consent:d.has('consent')};}}view=kind;render();}
function render(){if(view==='register'){register();return;}if(view==='account'&&state){cabinet();return;}if(view==='delete'){content.innerHTML=lead(t('Удалить профиль?','Профильді жою керек пе?'))+`<p>${t('Имя, настройки профиля и все зарегистрированные коды будут удалены из этого браузера.','Аты, профиль параметрлері және барлық тіркелген кодтар осы браузерден жойылады.')}</p><button class="button coral" style="margin-top:22px" data-action="confirm-delete">${t('Удалить','Жою')}</button> <button class="text-link" data-action="account">${t('Отмена','Бас тарту')}</button>`;return;}const privacy=view==='privacy';content.innerHTML=lead(privacy?t('Твои данные','Сенің деректерің'):t('Правила участия','Қатысу ережелері'))+`<div class="legal-copy">${privacy?`<p>${t('Профиль позволяет сохранять коды и отслеживать прогресс в этом браузере.','Профиль осы браузерде кодтарды сақтауға және ілгерілеуді бақылауға мүмкіндік береді.')}</p><p>${t('Профиль хранится в localStorage этого браузера: имя, город, возрастная группа, замаскированный телефон, время согласия и история кодов. Полный номер телефона не сохраняется.','Профиль осы браузердің localStorage жадында сақталады: аты, қаласы, жас тобы, жасырылған телефон нөмірі, келісім уақыты және кодтар тарихы. Толық телефон нөмірі сақталмайды.')}</p><p>${t('Сайт не отправляет форму на сервер и не посылает SMS. Удаление доступно в кабинете. Очистка данных браузера тоже удалит профиль.','Сайт форманы серверге жібермейді және SMS жолдамайды. Профильді кабинеттен жоюға болады. Браузер деректерін тазалау да профильді жояды.')}</p><p>${t('Хостинг может обрабатывать технические запросы для показа сайта. Общей базы покупателей и настоящей авторизации здесь нет.','Хостинг сайтты көрсету үшін техникалық сұрауларды өңдеуі мүмкін. Мұнда сатып алушылардың ортақ базасы және нақты авторизация жоқ.')}</p>`:`<p>${t('Регистрируй уникальные коды с упаковки и следи за прогрессом в личном кабинете.','Қаптамадағы бірегей кодтарды тіркеп, жеке кабинеттен ілгерілеуді бақыла.')}</p><ul><li>${t('Один код учитывается один раз.','Әр код бір рет есепке алынады.')}</li><li>${t('Уровни: 1 код — стикерпак, 3 — кружка, 5 — керамическая баночка.','Деңгейлер: 1 код — стикерпак, 3 — кесе, 5 — керамикалық құты.')}</li></ul><p>${t('Сроки акции и порядок получения подарков будут опубликованы после утверждения организатором.','Акция мерзімі мен сыйлық алу тәртібі ұйымдастырушы бекіткеннен кейін жарияланады.')}</p>`}</div><button class="dialog-back" data-action="${formDraft?'back-register':'close'}">${t('← Назад','← Артқа')}</button>`;}
function action(name){if(name==='join'||name==='try'){if(name==='try')pendingCode=DEMO_CODES.find(c=>!state?.codes.some(x=>x.code===c))??DEMO_CODES[0];tab='code';open(state?'account':'register');}else if(name==='account'){open(state?'account':'register');}else if(name==='close'){close();}else if(name==='privacy'||name==='rules'){if(dialog.open)legal(name);else open(name);}else if(name==='back-register'){view='register';render();}else if(name==='delete'){view='delete';render();}else if(name==='confirm-delete'){state=null;try{localStorage.removeItem('qurt-demo-v1');}catch{}close();notify(t('Профиль удалён.','Профиль жойылды.'));}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();action(target.dataset.action);}const languageButton=e.target.closest('[data-lang]');if(languageButton)language(languageButton.dataset.lang);const tabButton=e.target.closest('[data-tab]');if(tabButton){tab=tabButton.dataset.tab;render();}});
$('.dialog-close').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)close();}});language(lang);
